#!/usr/bin/env python3
"""Exact reverse-cone reachability generated by observed same-anchor return laws.

For an observed q0 RIGID endpoint m at anchor r, every reverse edge p -> m is
accepted only when an exact return certificate c satisfies replay(c,p)=m.
We search whether a finite chain reaches x=2^r p-1 below the original source n.

Bounded discovery only; the live return-law bank is finite and source-derived.
"""
from __future__ import annotations
import argparse,json
from collections import defaultdict,Counter,deque
from pathlib import Path

import collatz_stateful_future_kernel_v0 as fk
import collatz_q0_coalescence_component_audit as base
import collatz_q0_rigid_recharge_audit as ra


def totalR(c): return fk.vpz(c["A"],3)


def inverse_candidates(m, cs):
    out=[]
    for c in cs:
        num=(1<<c["D"])*m-c["B"]
        A=c["A"]
        if num<=0 or num%A: continue
        p=num//A
        if p<=0 or not (p&1): continue
        if not ra.admissible(c,p): continue
        if ra.replay(c,p)!=m: continue
        d=fk.defect(c,m)
        assert fk.vpz(d,3) is not None and fk.vpz(d,3)>=totalR(c)
        assert p-m==d//A
        out.append((p,c,fk.vpz(d,3)))
    return out


def shortest_lower(m,n,r,cs,max_depth,max_nodes):
    threshold=(n+1)/(1<<r)
    q=deque([(m,[])])
    seen={m}
    nodes=0
    while q and nodes<max_nodes:
        x,path=q.popleft(); nodes+=1
        if path and (1<<r)*x-1<n:
            return {"depth":len(path),"p":x,"source":(1<<r)*x-1,
                    "path":[fk.semantic_tuple(c) for c in path],"nodes":nodes}
        if len(path)>=max_depth: continue
        cands=inverse_candidates(x,cs)
        # consequential ordering only; search remains exhaustive within cap
        cands.sort(key=lambda z:(-z[2], z[0], fk.semantic_tuple(z[1])))
        for p,c,v3 in cands:
            if p not in seen:
                seen.add(p); q.append((p,path+[c]))
    return None


def greedy_nearest(m,n,r,cs,max_depth):
    x=m; path=[]
    seen={x}
    for _ in range(max_depth):
        cands=inverse_candidates(x,cs)
        if not cands: return None
        maxv=max(z[2] for z in cands)
        cands=[z for z in cands if z[2]==maxv]
        p,c,v=min(cands,key=lambda z:(z[0],fk.semantic_tuple(z[1])))
        path.append(c); x=p
        if (1<<r)*x-1<n:
            return {"depth":len(path),"p":x,"source":(1<<r)*x-1,
                    "path":[fk.semantic_tuple(c) for c in path]}
        if x in seen: return None
        seen.add(x)
    return None


def analyze(lo,hi,K,max_depth,max_nodes,out):
    pats=defaultdict(dict); events=[]; incomplete=[]
    for n in range(lo|1,hi+1,2):
        survives,_=base.survives_to_q0(n)
        if not survives or base.birth_status(n)[0]!="RIGID": continue
        if not fk.completed_rigid_source(n,K):
            incomplete.append(n); continue
        for r,seq in fk.return_sequences(n,K).items():
            if not seq: continue
            for e in seq:
                c=e["cert"]; pats[r][fk.semantic_id(c)]=c
                events.append((n,r,e["m0"],e["k0"]))
    bank={r:tuple(pats[r][k] for k in sorted(pats[r])) for r in sorted(pats)}

    # Unique protected obligations by (source,anchor,m).
    uniq=[]; seen=set()
    for z in events:
        key=z[:3]
        if key not in seen:
            seen.add(key); uniq.append(z)

    closed=[]; greedy=[]; residual=[]
    hist=Counter()
    for n,r,m,k0 in uniq:
        proof=shortest_lower(m,n,r,bank[r],max_depth,max_nodes)
        gp=greedy_nearest(m,n,r,bank[r],max_depth)
        if proof:
            closed.append({"n":n,"r":r,"m":m,"k0":k0,**proof})
            hist[proof["depth"]]+=1
        else:
            residual.append({"n":n,"r":r,"m":m,"k0":k0,
                             "valid_reverse_count":len(inverse_candidates(m,bank[r]))})
        if gp: greedy.append({"n":n,"r":r,"m":m,"k0":k0,**gp})

    # independent replay of every closure chain, from lower source forward
    replay_checks=0
    for z in closed:
        p=z["p"]; target=z["m"]; r=z["r"]
        # path stored in reverse-search order: c1 maps p1->start? Actually each
        # newly found p is prepended relative to current x; replay in reverse.
        x=p
        certs=[]
        for tup in reversed(z["path"]):
            c=next(c for c in bank[r] if fk.semantic_tuple(c)==tuple(tup))
            certs.append(c)
            assert ra.admissible(c,x)
            x=ra.replay(c,x); replay_checks+=1
        assert x==target,(z,x,target)

    result={
      "range":[lo|1,hi],"K":K,"max_depth":max_depth,"max_nodes":max_nodes,
      "incomplete_sources":incomplete,
      "return_laws":sum(len(v) for v in bank.values()),
      "unique_obligations":len(uniq),
      "closed":len(closed),"residual":len(residual),
      "greedy_nearest_closed":len(greedy),
      "depth_histogram":{str(k):v for k,v in sorted(hist.items())},
      "replay_checks":replay_checks,
      "closed_sample":closed[:30],
      "residual_sample":residual[:30],
      "scope":"finite observed same-anchor return-law bank; bounded reverse BFS only"
    }
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps(result,indent=2,sort_keys=True)+"\n")
    for k in ("return_laws","unique_obligations","closed","residual","greedy_nearest_closed","depth_histogram","replay_checks"):
        print(k.upper(),json.dumps(result[k],sort_keys=True) if isinstance(result[k],dict) else result[k])
    print("RESIDUAL_SAMPLE",json.dumps(result["residual_sample"],sort_keys=True))
    print("CLOSED_SAMPLE",json.dumps(result["closed_sample"],sort_keys=True))


if __name__=="__main__":
    ap=argparse.ArgumentParser()
    ap.add_argument("--lo",type=int,default=46081); ap.add_argument("--hi",type=int,default=46591)
    ap.add_argument("--K",type=int,default=128); ap.add_argument("--max-depth",type=int,default=8)
    ap.add_argument("--max-nodes",type=int,default=50000); ap.add_argument("--output",type=Path,required=True)
    a=ap.parse_args(); analyze(a.lo,a.hi,a.K,a.max_depth,a.max_nodes,a.output)
